const G=2,S=1.1;
const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-0.7071068,0,0,0.7071068],down:[0.7071068,0,0,0.7071068],right:[0,0,-0.7071068,0.7071068],left:[0,0,0.7071068,0.7071068]};
const pos=(c,r,y)=>[(c-1)*S,y,(1-r)*S];
const dist=s=>(G-s.c)+(G-s.r);
export function initialState(){return {c:0,r:0,moves:0,hint:false,msg:'Reach the orange goal. Shortest route: 4 moves.'};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const s={...state};
if(dist(s)===0)return state;
if(event.action==='hintBtn'){s.hint=true;s.msg='Hint: the green arrow shows a move one step closer.';return s;}
const d=D[event.action];if(!d)return state;
const c=s.c+d[0],r=s.r+d[1];
if(c<0||c>2||r<0||r>2){s.msg='That move would leave the board.';return s;}
s.c=c;s.r=r;s.moves++;s.hint=false;
const k=dist(s);
if(k===0){s.msg=s.moves===4?'You reached the goal in 4 moves: the shortest route!':'You reached the goal in '+s.moves+' moves; the shortest route is 4.';}
else s.msg='Moved '+event.action+'. '+k+(k===1?' step':' steps')+' to go.';
return s;}
export function evaluate({state}){
const s=state||initialState();
const k=dist(s),won=k===0;
const hd=s.c<G?'right':'up';
return {nodes:{token:{position:pos(s.c,s.r,0.35)},hintA:{visible:s.hint&&!won,position:pos(s.c,s.r,0.35),quaternion:Q[hd]}},
materials:{goal:{color:won?'#2fa84f':'#f08a24'}},
readouts:{moves:s.moves,dist:k},
goal:{status:won?'won':'playing',message:s.msg}};}
